B=[
('الْبَحْثُ عَنِ الْمَوْضِعِ','Yerin araştırılması',[
('فَطَمِعَ أَنْ يَعْثُرَ عَلَى مَوْضِعِ الْآفَةِ فَيُزِيلَهَا عَنْهَا، فَتَرْجِعَ إِلَى مَا كَانَتْ عَلَيْهِ.','Kusurun yerini bulup onu gidermeyi ve ceylanın eski hâline dönmesini umdu.'),
('فَفَكَّرَ وَقَالَ: إِنَّ هَذَا الْفِعْلَ لَيْسَ يَصْدُرُ عَنِ الْعُضْوِ الظَّاهِرِ، بَلْ عَنْ شَيْءٍ فِي بَاطِنِ الْجَسَدِ.','Düşündü ve dedi ki: Bu fiil dış uzuvdan değil, bedenin içindeki bir şeyden kaynaklanıyor.'),
('وَرَأَى أَنَّ ذَلِكَ الشَّيْءَ يَسْكُنُ عُضْوًا وَسَطَ الْجَسَدِ، هُوَ الْقَلْبُ.','O şeyin bedenin ortasındaki bir uzuvda, kalpte bulunduğunu düşündü.'),
('فَشَقَّ صَدْرَهَا بِحَجَرٍ حَادٍّ وَأَشْيَاءَ مِنَ الْقَصَبِ الْيَابِسَةِ.','Keskin bir taşla ve kuru kamış parçalarıyla göğsünü yardı.'),
('فَوَجَدَ الْقَلْبَ، وَوَجَدَ فِي أَحَدِ جَانِبَيْهِ تَجْوِيفًا فَارِغًا.','Kalbi buldu ve onun iki tarafından birinde boş bir oyuk buldu.'),
('فَقَالَ: إِنَّ السَّاكِنَ الَّذِي كَانَ هُنَا قَدْ رَحَلَ عَنْهُ، وَتَرَكَ الْبَيْتَ خَالِيًا.','Dedi ki: Burada oturan, buradan göçüp gitmiş ve evi boş bırakmış.'),
('فَعَلِمَ أَنَّ الْجَسَدَ كُلَّهُ إِنَّمَا هُوَ كَالْآلَةِ لِذَلِكَ الشَّيْءِ.','Bütün bedenin o şey için bir alet gibi olduğunu anladı.')]),
('مَا هُوَ ذَلِكَ الشَّيْءُ؟','O şey nedir?',[
('فَأَخَذَ يُفَكِّرُ فِي ذَلِكَ الشَّيْءِ: مَا هُوَ؟ وَكَيْفَ هُوَ؟ وَمَا الَّذِي رَبَطَهُ بِهَذَا الْجَسَدِ؟','O şey hakkında düşünmeye başladı: O nedir? Nasıldır? Onu bu bedene bağlayan nedir?'),
('وَإِلَى أَيْنَ صَارَ؟ وَمِنْ أَيِّ الْأَبْوَابِ خَرَجَ؟','Nereye gitti? Hangi kapıdan çıktı?'),
('وَرَأَى أَنَّ أُمَّهُ الَّتِي عَطَفَتْ عَلَيْهِ وَأَرْضَعَتْهُ إِنَّمَا كَانَتْ ذَلِكَ الشَّيْءَ الْمُرْتَحِلَ.','Kendisine şefkat gösteren ve onu emziren annesinin aslında o göçüp giden şey olduğunu gördü.'),
('وَأَنَّ هَذَا الْجَسَدَ الْمُتَعَطِّلَ إِنَّمَا كَانَ آلَةً لَهَا.','Ve bu hareketsiz bedenin onun için yalnızca bir alet olduğunu.'),
('فَانْصَرَفَتْ مَحَبَّتُهُ عَنِ الْجَسَدِ إِلَى صَاحِبِ الْجَسَدِ.','Sevgisi bedenden bedenin sahibine yöneldi.'),
('ثُمَّ إِنَّ الْجَسَدَ أَنْتَنَ، فَرَأَى غُرَابَيْنِ يَقْتَتِلَانِ حَتَّى صَرَعَ أَحَدُهُمَا الْآخَرَ.','Sonra beden koktu; iki karganın birbiriyle dövüştüğünü, sonunda birinin ötekini öldürdüğünü gördü.'),
('ثُمَّ جَعَلَ الْحَيُّ يَبْحَثُ فِي الْأَرْضِ حَتَّى حَفَرَ حُفْرَةً، فَوَارَى فِيهَا الْمَيِّتَ.','Sonra yaşayan karga toprağı eşelemeye başladı, bir çukur kazdı ve ölüyü içine gömdü.'),
('فَقَالَ حَيٌّ: مَا أَحْسَنَ مَا صَنَعَ هَذَا الْغُرَابُ! فَحَفَرَ حُفْرَةً، وَدَفَنَ فِيهَا أُمَّهُ.','Hayy dedi ki: Bu karga ne güzel yaptı! Bir çukur kazdı ve annesini oraya gömdü.')]),
('النَّارُ','Ateş',[
('وَاتَّفَقَ فِي بَعْضِ الْأَوْقَاتِ أَنِ انْقَدَحَتْ نَارٌ فِي أَجَمَةِ قَصَبٍ عَلَى سَبِيلِ الْمُحَاكَّةِ.','Bir zaman sürtünme yoluyla bir kamışlıkta ateş çaktı.'),
('فَلَمَّا بَصُرَ بِهَا رَأَى مَنْظَرًا هَالَهُ، وَخَلْقًا لَمْ يَعْهَدْهُ قَبْلُ.','Onu görünce kendisini dehşete düşüren bir manzara, daha önce bilmediği bir yaratık gördü.'),
('فَوَقَفَ يَتَعَجَّبُ مِنْهَا مَلِيًّا، وَمَا زَالَ يَدْنُو مِنْهَا شَيْئًا فَشَيْئًا.','Uzun süre durup ona hayret etti ve azar azar ona yaklaşmaya devam etti.'),
('فَرَأَى مَا لِلنَّارِ مِنَ الضَّوْءِ الثَّاقِبِ، وَالْفِعْلِ الْغَالِبِ، حَتَّى لَا تَعْلَقُ بِشَيْءٍ إِلَّا أَتَتْ عَلَيْهِ.','Ateşteki delip geçen ışığı ve galip gelen etkiyi gördü; öyle ki ateş neye tutunursa onu yok ediyordu.'),
('فَمَدَّ يَدَهُ إِلَيْهَا، فَأَحْرَقَتْ أَصَابِعَهُ، فَعَلِمَ أَنَّهُ لَا يَسْتَطِيعُ أَنْ يَقْبِضَ عَلَيْهَا.','Elini ona uzattı; parmaklarını yaktı ve onu tutamayacağını anladı.'),
('فَأَخَذَ قَبَسًا مِنْهَا بِطَرَفِ غُصْنٍ لَمْ تَسْتَوْلِ النَّارُ عَلَى جَمِيعِهِ، وَحَمَلَهُ إِلَى مَوْضِعِهِ.','Ateşin tamamını sarmadığı bir dalın ucuyla ondan bir kor aldı ve kendi yerine taşıdı.'),
('وَكَانَ يَتَعَهَّدُهَا بِالْحَطَبِ لَيْلًا وَنَهَارًا، وَيَأْنَسُ بِهَا فِي اللَّيْلِ.','Gece gündüz ona odun atarak bakar ve gece onunla ünsiyet bulurdu.'),
('وَظَنَّ أَنَّ الشَّيْءَ الَّذِي ارْتَحَلَ مِنْ قَلْبِ أُمِّهِ الظَّبْيَةِ كَانَ مِنْ جَوْهَرِ هَذَا الْمَوْجُودِ.','Ceylan annesinin kalbinden göçüp giden şeyin bu varlığın cevherinden olduğunu sandı.')]),
('الْحَيَوَانُ الْحَيُّ','Canlı hayvan',[
('فَأَخَذَ حَيَوَانًا مِنَ الْوَحْشِ، وَشَقَّ قَلْبَهُ وَهُوَ حَيٌّ.','Vahşi hayvanlardan birini aldı ve o canlıyken kalbini açtı.'),
('فَوَجَدَ فِي التَّجْوِيفِ الَّذِي كَانَ فَارِغًا فِي أُمِّهِ بُخَارًا حَارًّا كَأَنَّهُ ضَبَابٌ أَبْيَضُ.','Annesinde boş olan oyukta beyaz bir sise benzeyen sıcak bir buhar buldu.'),
('فَأَدْخَلَ فِيهِ إِصْبَعَهُ فَوَجَدَهُ مِنَ الْحَرَارَةِ بِحَيْثُ كَادَ يُحْرِقُهُ.','Parmağını içine soktu ve onu neredeyse yakacak kadar sıcak buldu.'),
('وَمَاتَ الْحَيَوَانُ عَلَى الْفَوْرِ.','Hayvan hemen öldü.'),
('فَصَحَّ عِنْدَهُ أَنَّ ذَلِكَ الْبُخَارَ الْحَارَّ هُوَ الَّذِي يُحَرِّكُ الْحَيَوَانَ.','Hayvanı hareket ettirenin o sıcak buhar olduğu onun nezdinde kesinleşti.'),
('وَأَنَّ فِي كُلِّ شَخْصٍ مِنْ أَشْخَاصِ الْحَيَوَانِ مِثْلَهُ، فَإِذَا انْفَصَلَ عَنْهُ مَاتَ.','Ve hayvanların her bir ferdinde onun benzeri olduğunu, ondan ayrılınca öldüğünü.'),
('فَسَمَّاهُ الرُّوحَ الْحَيَوَانِيَّ، وَلَمْ يَكُنْ يَعْرِفُ بَعْدُ أَنَّ وَرَاءَهُ شَيْئًا أَشْرَفَ مِنْهُ.','Ona hayvanî ruh adını verdi; henüz onun ardında ondan daha şerefli bir şey olduğunu bilmiyordu.')]),
('الصِّنَاعَاتُ','Sanatlar',[
('ثُمَّ إِنَّهُ اتَّخَذَ مِنْ جُلُودِ الْحَيَوَانَاتِ الَّتِي كَانَ يُشَرِّحُهَا ثِيَابًا يَكْتَسِي بِهَا.','Sonra incelediği hayvanların derilerinden giyindiği elbiseler yaptı.'),
('وَاتَّخَذَ مِنَ الشُّعُورِ وَلِحَاءِ الْأَشْجَارِ خُيُوطًا، وَمِنَ الشَّوْكِ مَخَارِزَ.','Kıllardan ve ağaç kabuklarından iplikler, dikenlerden bızlar yaptı.'),
('وَتَعَلَّمَ الْبِنَاءَ مِنْ مُشَاهَدَةِ الْخَطَاطِيفِ، فَاتَّخَذَ مَخْزَنًا وَبَيْتًا لِفَضْلَةِ غِذَائِهِ.','Kırlangıçları seyrederek yapı yapmayı öğrendi; artan yiyeceği için bir ambar ve bir ev edindi.'),
('وَحَصَّنَهُ بِبَابٍ مِنَ الْقَصَبِ الْمَرْبُوطِ بَعْضُهُ إِلَى بَعْضٍ.','Onu birbirine bağlanmış kamışlardan bir kapıyla korudu.'),
('وَاسْتَأْلَفَ جَوَارِحَ الطَّيْرِ لِيَسْتَعِينَ بِهَا فِي الصَّيْدِ.','Avda yardım alması için yırtıcı kuşları evcilleştirdi.'),
('وَاتَّخَذَ مِنَ الدَّجَاجِ مَا يَنْتَفِعُ بِبَيْضِهِ وَفِرَاخِهِ.','Yumurtasından ve civcivlerinden faydalanacağı tavuklar edindi.'),
('وَاسْتَعَانَ بِالْخَيْلِ عَلَى قَطْعِ الْمَسَافَاتِ، فَبَلَغَ مَا لَمْ يَكُنْ يَبْلُغُهُ قَبْلُ.','Mesafeleri katetmek için atlardan yardım aldı ve daha önce ulaşamadığı yerlere ulaştı.')]),
('الْأَجْسَامُ','Cisimler',[
('ثُمَّ تَشَوَّقَ إِلَى أَنْ يَنْظُرَ فِي جَمِيعِ الْأَجْسَامِ الَّتِي فِي عَالَمِ الْكَوْنِ وَالْفَسَادِ.','Sonra oluş ve bozuluş âlemindeki bütün cisimleri incelemeyi arzuladı.'),
('فَرَأَى الْحَيَوَانَاتِ وَالنَّبَاتَ وَالْمَعَادِنَ وَأَصْنَافَ الْحِجَارَةِ وَالتُّرَابِ وَالْمَاءِ وَالْبُخَارِ وَالثَّلْجِ وَالدُّخَانِ وَالنَّارِ.','Hayvanları, bitkileri, madenleri, taş çeşitlerini, toprağı, suyu, buharı, karı, dumanı ve ateşi gördü.'),
('فَرَآهَا ذَاتَ أَوْصَافٍ كَثِيرَةٍ مُخْتَلِفَةٍ، وَرَأَى أَنَّهَا تَتَّفِقُ بِبَعْضِ الصِّفَاتِ وَتَخْتَلِفُ بِبَعْضٍ.','Onları birçok farklı vasıflara sahip gördü; bazı sıfatlarda birleştiklerini, bazılarında ayrıldıklarını gördü.'),
('فَنَظَرَ إِلَى الْحَيَوَانِ كُلِّهِ فَرَآهُ شَيْئًا وَاحِدًا بِالرُّوحِ الَّذِي يَسْرِي فِيهِ.','Bütün hayvanlara baktı ve onları, içlerinde dolaşan ruh sayesinde tek bir şey olarak gördü.'),
('ثُمَّ رَأَى الْحَيَوَانَ وَالنَّبَاتَ شَيْئًا وَاحِدًا فِي الِاغْتِذَاءِ وَالنُّمُوِّ.','Sonra hayvanları ve bitkileri beslenme ve büyümede tek bir şey olarak gördü.'),
('ثُمَّ رَأَى الْأَجْسَامَ كُلَّهَا شَيْئًا وَاحِدًا فِي الِامْتِدَادِ فِي الطُّولِ وَالْعَرْضِ وَالْعُمْقِ.','Sonra bütün cisimleri uzunluk, genişlik ve derinlikte yayılmada tek bir şey olarak gördü.'),
('فَتَبَيَّنَ لَهُ أَنَّ الْكَثْرَةَ إِنَّمَا تَرْجِعُ إِلَى وَحْدَةٍ.','Çokluğun ancak bir birliğe döndüğü ona açıkça göründü.')]),
('الصُّورَةُ وَالْفَاعِلُ','Suret ve fâil',[
('ثُمَّ نَظَرَ إِلَى الْمَاءِ، فَرَآهُ إِذَا سُخِّنَ صَارَ بُخَارًا، وَإِذَا بُرِّدَ صَارَ ثَلْجًا.','Sonra suya baktı; ısıtılınca buhar, soğutulunca kar olduğunu gördü.'),
('فَعَلِمَ أَنَّ لِلْجِسْمِ صُورَةً تَتَبَدَّلُ عَلَيْهِ، وَأَنَّ الْجِسْمَ بَاقٍ.','Cismin üzerinde değişen bir sureti olduğunu, cismin ise kaldığını anladı.'),
('وَرَأَى أَنَّ كُلَّ حَادِثٍ لَا بُدَّ لَهُ مِنْ مُحْدِثٍ.','Her sonradan olanın mutlaka bir meydana getireni olması gerektiğini gördü.'),
('فَإِنَّ الصُّورَةَ إِذَا حَدَثَتْ بَعْدَ أَنْ لَمْ تَكُنْ، فَلَا بُدَّ لَهَا مِنْ فَاعِلٍ أَحْدَثَهَا.','Çünkü suret yokken meydana gelince, onu meydana getiren bir fâil mutlaka olmalıdır.'),
('فَطَلَبَ ذَلِكَ الْفَاعِلَ فِي الْأَجْسَامِ الَّتِي حَوْلَهُ، فَلَمْ يَجِدْهُ.','O fâili etrafındaki cisimlerde aradı ama bulamadı.'),
('لِأَنَّ كُلَّ جِسْمٍ مِنْهَا حَادِثٌ مُفْتَقِرٌ إِلَى مُحْدِثٍ.','Çünkü onlardan her cisim sonradan olmuştur ve bir meydana getirene muhtaçtır.'),
('فَعَلِمَ أَنَّ الْفَاعِلَ لَيْسَ بِجِسْمٍ، وَأَنَّهُ يَجِبُ أَنْ يَكُونَ بَرِيئًا عَنِ الْمَادَّةِ.','Fâilin cisim olmadığını ve maddeden münezzeh olması gerektiğini anladı.')]),
]
